-- TOR-142: route codes are generated by the database instead of the dashboard.
-- New routes get R-00001, R-00002, ... from a global sequence, so two admins
-- creating a route at the same time can never collide, and `code` is UNIQUE.
-- Existing routes keep the code they have (the old client-generated
-- R-<YYYYMMDD>-<nn> format never matches the new one, so there is no clash).

CREATE SEQUENCE IF NOT EXISTS public.routes_code_seq AS bigint START 1;

CREATE OR REPLACE FUNCTION public.next_route_code ()
  RETURNS text
  LANGUAGE sql
  VOLATILE
  SET search_path = public
  AS $function$
  -- lpad() truncates when the text is longer than the width, so the width
  -- grows with the number once it passes 99999.
  SELECT 'R-' || lpad(n::text, greatest(5, length(n::text)), '0')
  FROM (SELECT nextval('public.routes_code_seq') AS n) AS seq;
$function$;

-- The old format had no UNIQUE constraint, so two routes of the same day may
-- already share a code. Keep the oldest as is and suffix the others, otherwise
-- the constraint below would fail to apply.
WITH ranked AS (
  SELECT id, code,
         row_number() OVER (PARTITION BY code ORDER BY created_at, id) AS n
  FROM public.routes
)
UPDATE public.routes r
SET code = ranked.code || '-' || ranked.n
FROM ranked
WHERE r.id = ranked.id AND ranked.n > 1;

ALTER TABLE public.routes
  ALTER COLUMN code SET DEFAULT public.next_route_code (),
  ADD CONSTRAINT routes_code_key UNIQUE (code);
